package pe.edu.utp.thanosgym.auth.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="usuarios",uniqueConstraints=@UniqueConstraint(name="uk_usuario",columnNames="usuario")) public class Usuario{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long idUsuario;@Column(nullable=false,length=50) private String usuario;@Column(nullable=false,length=100) private String passwordHash;@Column(nullable=false,length=100) private String nombre;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Rol rol;@Column(nullable=false) private boolean activo=true;@Column(nullable=false) private int intentosFallidos=0;private LocalDateTime bloqueadoHasta;
 public Long getIdUsuario(){return idUsuario;}public String getUsuario(){return usuario;}public void setUsuario(String v){usuario=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public String getNombre(){return nombre;}public void setNombre(String v){nombre=v;}public Rol getRol(){return rol;}public void setRol(Rol v){rol=v;}public boolean isActivo(){return activo;}public void setActivo(boolean v){activo=v;}public int getIntentosFallidos(){return intentosFallidos;}public void setIntentosFallidos(int v){intentosFallidos=v;}public LocalDateTime getBloqueadoHasta(){return bloqueadoHasta;}public void setBloqueadoHasta(LocalDateTime v){bloqueadoHasta=v;}
}
